import cf from 'cloudfront';
const kvs = cf.kvs();

async function handler(event) {
    const request = event.request;
    let banner = 'sem-kvs';
    try {
        banner = await kvs.get('banner');
    } catch (e) {
        banner = 'chave-ausente';
    }
    request.headers['x-struct8-banner'] = { value: banner };
    return request;
}

